using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using MapSharedProps.EditorTools;
public static class Grave97Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Dictionary<string,GameObject> Build(string stage){string folder="Assets/Imported97-"+stage;Check(!AssetDatabase.IsValidFolder(folder),"Use fresh output folder");AssetDatabase.CreateFolder("Assets",folder.Substring(7));var root=new GameObject("Graves "+stage);var p=new Dictionary<string,GameObject>();int placed=SmallPropsV1.Build(Path.Combine(Root,"Input97-"+stage),folder,root.transform,Shader.Find("MapSharedProps/Lit"),p);Check(p.Count==43&&placed==2,"43 prefabs and two placements");PrefabUtility.SaveAsPrefabAsset(root,"Assets/grave97-"+stage+".prefab");UnityEngine.Object.DestroyImmediate(root);AssetDatabase.SaveAssets();return p;}
 public static void Run(){int exit=0;string output=Path.Combine(Root,"Evidence97Import");Directory.CreateDirectory(output);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var before=Build("before");var after=Build("after");var absent=Build("absent");foreach(var id in new[]{"gravestone","crossgrave"}){var a=before[id].GetComponent<MeshCollider>().sharedMesh;var b=after[id].GetComponent<MeshCollider>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.triangles.SequenceEqual(b.triangles),"unchanged collider "+id);var m=after[id].GetComponent<MeshFilter>().sharedMesh;Check(m.vertexCount<4500&&m.normals.Length==m.vertexCount,"mesh budget/normal");Check(m.vertices.All(v=>float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z)),"finite mesh");var tex=after[id].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap");Check(tex&&tex.width==128&&tex.height==128,"stone atlas");var old=absent[id].GetComponent<Renderer>().sharedMaterial.GetTexture("_BaseMap");Check(!old||old==Texture2D.whiteTexture||old.width<=2,"absent map fallback");}Check(after["gravestone"].GetComponent<Renderer>().sharedMaterial==after["crossgrave"].GetComponent<Renderer>().sharedMaterial,"shared material");foreach(var id in before.Keys.Where(x=>x!="gravestone"&&x!="crossgrave")){var a=before[id].GetComponent<MeshFilter>().sharedMesh;var b=after[id].GetComponent<MeshFilter>().sharedMesh;Check(a==b,"unrelated cached mesh "+id);}File.WriteAllText(Path.Combine(output,"checks.json"),"{\"pass\":true,\"cases\":[\"before\",\"after\",\"absentSurface\"],\"prefabsPerCase\":43,\"placedPerCase\":2,\"colliderVerticesAndIndicesExact\":true,\"unrelatedMeshesExact\":true,\"shared128TextureMaterial\":true,\"readerSourceUnchanged\":true,\"playerExecuted\":false}");}catch(Exception e){Debug.LogException(e);File.WriteAllText(Path.Combine(output,"error.txt"),e.ToString());exit=1;}finally{EditorApplication.Exit(exit);}}
}
